  applySettings(s:Settings){if(this.hitCloud&&this.settings.blood&&!s.blood){const colors=this.hitCloud.geometry.getAttribute('color') as T.BufferAttribute;for(let i=0;i<this.hitParticles.length;i++)colors.setXYZ(i,.64,.66,.56);colors.needsUpdate=true;}this.settings=s;this.ui.settings=s;this.audio.setVolume(s.volume);this.renderer.setPixelRatio(Math.min(devicePixelRatio,s.quality==='low'?CONFIG.render.lowDpr:CONFIG.render.highDpr,Math.sqrt((s.quality==='low'?CONFIG.render.lowPixels:CONFIG.render.highPixels)/(innerWidth*innerHeight))));this.renderer.shadowMap.enabled=s.quality==='high';this.renderer.shadowMap.type=T.PCFSoftShadowMap;this.world.moon.castShadow=s.quality==='high';this.renderer.setSize(innerWidth,innerHeight);}
