  private spawn(a:Actor){let best:T.Vector3|undefined,bestScore=-Infinity;const eye=new T.Vector3(),d=new T.Vector3();for(const candidate of this.world.teamSpawns[a.team]){const p=this.world.physics.spawnPosition(candidate);if(!p||this.actors.some(o=>o!==a&&o.health>0&&o.pos.distanceTo(p)<1.15))continue;let nearest=100,exposure=0;for(const o of this.actors){if(o.team===a.team||o.health<=0)continue;const dist=p.distanceTo(o.pos);nearest=Math.min(nearest,dist);eyePosition(o,eye);d.copy(p).y+=1.57;d.sub(eye).normalize();if(this.world.physics.ray(eye,d,dist)>dist-.3)exposure+=24/(1+dist*.035);}const score=nearest-exposure;if(score>bestScore){bestScore=score;best=p;}}if(!best){a.dead=.1;return;}a.reset(best);a.grounded=true;a.yaw=a.team==='blue'?0:Math.PI;a.think=a.id*.025;if(a.id===0){this.recoil=0;this.ads=0;this.eyeHeight=CONFIG.player.eye;this.clearInput();this.notice('REDEPLOYED / SPAWN SHIELD ACTIVE');}}
