      if(this.elapsed-victim.lastFlinch>=CONFIG.hitEffects.reactionInterval){victim.motion.hit=.2;victim.motion.hitSide=Math.sin(a.yaw-victim.yaw)>=0?1:-1;victim.lastFlinch=this.elapsed;}
      if(killed){victim.lastKiller=a.name;victim.weapon.cancelReload();victim.stance.cancel();victim.flash.visible=false;this.ui.addKill(`<span class="${a.team}">${a.name}</span> / ${result.head?'HEADSHOT':'ELIM'} / <span class="${victim.team}">${victim.name}</span>`,this.elapsed);if(a.id===0){this.notice(`+1 / ${victim.name} ELIMINATED`);this.audio.play('eliminate');}if(victim.id===0){this.clearInput();this.recoil=0;this.ads=0;}this.outcome=matchResult(this.elapsed,teamScores(this.actors));}
