    if(this.flashTime===0){this.flashLight.intensity=0;for(const a of this.actors)a.flash.visible=false;}
    for(const e of this.effects)if(e.time>0){e.time-=dt;e.line.visible=e.time>.155&&!this.settings.reduced;e.impact.position.addScaledVector(e.vel,dt);e.vel.y-=dt*5;if(e.time<=0)e.impact.visible=false;}
